const tabs=document.querySelector('#tabs'),preview=document.querySelector('#preview'),overflow=document.querySelector('#overflow');
let notes=[],dragging=null,uiScale=1;
const shapes={dot:'<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="6" fill="currentColor" stroke="none"/></svg>',star:'<svg viewBox="0 0 24 24"><path d="m12 3 2.7 5.5 6.1.9-4.4 4.3 1 6.1-5.4-2.9-5.4 2.9 1-6.1-4.4-4.3 6.1-.9z" fill="currentColor" stroke="none"/></svg>',bulb:'<svg viewBox="0 0 24 24"><path d="M9 18h6m-5 3h4m4-11a6 6 0 1 0-10.4 4.1C8.5 15 9 16 9 17h6c0-1 .5-2 1.4-2.9A5.9 5.9 0 0 0 18 10Z"/></svg>',check:'<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="m8 12 2.6 2.7L16.5 9"/></svg>',flag:'<svg viewBox="0 0 24 24"><path d="M6 21V4m0 1h11l-2 4 2 4H6"/></svg>',heart:'<svg viewBox="0 0 24 24"><path d="M20 8.7C20 14 12 19 12 19S4 14 4 8.7C4 5.4 8 4 10.1 6.5L12 8.7l1.9-2.2C16 4 20 5.4 20 8.7Z"/></svg>'};
function regions(){const elements=[tabs,preview,overflow].filter(element=>!element.hidden&&(element===preview||element.children.length));window.pindoNative.command('dock-regions',elements.map(element=>{const r=element.getBoundingClientRect();return{x:r.x,y:r.y,width:r.width,height:r.height};}));}
function hidePreview(){preview.hidden=true;requestAnimationFrame(regions);}
function tab(note){
  const button=document.createElement('button');button.className='tab';button.draggable=true;button.style.setProperty('--tint',note.color||'#eee');button.style.setProperty('--icon',note.iconColor||'#f58b56');
  const icon=document.createElement('i');icon.innerHTML=shapes[note.icon]||shapes.dot;const title=document.createElement('strong');title.textContent=note.title;button.append(icon,title);button.onclick=()=>window.pindoNative.command('dock-restore',note.id);
  button.onmouseenter=()=>{window.pindoNative.command('dock-hover',true);preview.replaceChildren();if(note.type==='todo'){const count=document.createElement('b');count.textContent=note.count;preview.append(count);}const heading=document.createElement('strong');heading.textContent=note.title;preview.append(heading);if(note.summary){const detail=document.createElement('p');detail.textContent=note.type==='timeline'?`本周要进行【${note.summary}】`:note.summary;preview.append(detail);}preview.hidden=false;preview.style.top=Math.max(8,Math.min(button.getBoundingClientRect().top,innerHeight-preview.offsetHeight-8))+'px';requestAnimationFrame(regions);};
  button.onmouseleave=()=>{window.pindoNative.command('dock-hover',false);hidePreview();};button.ondragstart=()=>{dragging=note.id;hidePreview();};
  button.ondragover=event=>{event.preventDefault();document.querySelectorAll('.tab.over-before,.tab.over-after').forEach(x=>x.classList.remove('over-before','over-after'));const after=event.clientY>button.getBoundingClientRect().top+button.offsetHeight/2;button.classList.add(after?'over-after':'over-before');};
  button.ondragleave=()=>button.classList.remove('over-before','over-after');button.ondrop=event=>{event.preventDefault();const after=event.clientY>button.getBoundingClientRect().top+button.offsetHeight/2;button.classList.remove('over-before','over-after');if(dragging&&dragging!==note.id)window.pindoNative.command('dock-reorder',{id:dragging,target:note.id,after});};
  button.ondragend=()=>{dragging=null;document.querySelectorAll('.tab.over-before,.tab.over-after').forEach(x=>x.classList.remove('over-before','over-after'));hidePreview();};return button;
}
function render(){preview.hidden=true;tabs.replaceChildren();overflow.replaceChildren();overflow.hidden=true;const limit=Math.max(1,Math.floor((innerHeight-95*uiScale)/(62*uiScale)));notes.slice(0,limit).forEach(note=>tabs.append(tab(note)));if(notes.length>limit){const more=document.createElement('button');more.className='tab more';more.textContent='•••';more.title='更多便签';more.onclick=()=>{overflow.hidden=!overflow.hidden;regions();};tabs.append(more);notes.slice(limit).forEach(note=>overflow.append(tab(note)));}requestAnimationFrame(regions);}
window.pindoNative.on('dock-state',value=>{notes=value;render();});window.addEventListener('resize',render);window.pindoNative.command('dock-list').then(value=>{notes=value||[];render();});
function closePreview(){preview.hidden=true;overflow.hidden=true;regions();}window.pindoNative.on('pointer-outside',closePreview);window.addEventListener('blur',closePreview);document.documentElement.addEventListener('mouseleave',closePreview);
window.pindoNative.on('dock-settings',settings=>{uiScale={small:.88,medium:1,large:1.14}[settings.uiSize]||1;document.documentElement.style.setProperty('--scale',uiScale);render();});
